<?php require '../includes/auth.php';require_role('admin');$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare('UPDATE products SET is_available=0 WHERE id=?')->execute([(int)post('id')]);flash('success','Product removed from marketplace.');redirect('admin/products.php');}$products=$pdo->query('SELECT p.*,sp.shop_name FROM products p JOIN seller_profiles sp ON sp.id=p.seller_id ORDER BY p.created_at DESC')->fetchAll();$pageTitle='Marketplace products';require '../includes/header.php';?><div class="page-title"><p class="eyebrow">ADMIN</p><h1>Product listings</h1></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Shop</th><th>Price</th><th>Stock</th><th></th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['shop_name'])?></td><td>₹<?=$p['price']?></td><td><?=$p['stock']?> kg</td><td><?php if($p['is_available']):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="text-button" data-confirm="Remove this listing from buyers?">Remove</button></form><?php else:?>Removed<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php require '../includes/footer.php'; ?>
